function buildBody(article) {
  const sections = article.sections
    .map((section) => `## ${section.heading}\n${section.body}`)
    .join("\n\n");
  const checklist = article.checklist.map((item) => `- ${item}`).join("\n");
  const faqs = article.faqs
    .map((faq) => `### ${faq.question}\n${faq.answer}`)
    .join("\n\n");

  return `## Direct Answer\n${article.directAnswer}\n\n${sections}\n\n## Buyer Checklist\n${checklist}\n\n## FAQ\n${faqs}\n\n## Next Step\n${article.nextStep}`;
}

function defineArticle(article) {
  const cluster = businessKeywordClusters.find((entry) => entry.id === article.clusterId);

  if (!cluster) {
    throw new Error(`Missing keyword cluster for ${article.slug}`);
  }

  return {
    ...article,
    body: buildBody(article),
    seoKeywords: [...coreBusinessKeywords, ...cluster.keywords],
    imageFilename: `${article.slug}.webp`,
  };
}

